mapper.select:
select ir.id as id,ir.create_time as createTime,ir.order_sn as orderSn,ir.user_id as userId,ir.money as money,ir.integral as integral,ir.pay_type as payType, ir.recharge_status as rechargeStatus,su.nickname as userName,su.avatar as userAvatar,su.phone as userPhone from integral_recharge ir left join sys_user su on su.id=ir.user_id WHERE 1=1
AND ir.user_id = #{params.userId}
AND ir.pay_type = #{params.payType}
AND ir.recharge_status = #{params.rechargeStatus}
and ( su.nickname like CONCAT('%',#{params.keyword},'%') or su.phone like CONCAT('%',#{params.keyword},'%') )
order by ir.create_time desc
